INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("青空の下で謁見", 1, 91002, 10118, 5118061, "フリーマーケットを訪れたジータが出会ったのは\n城をこっそり抜け出していたペコリーヌだった。", 20063115, "ペコリーヌとの出会い", "フリーマーケット会場", 7, 0, 8, 40, 2, 2834);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("未来の騎空団\nマスコット？", 1, 91002, 10118, 5118062, "ジータたちがフリーマーケットを巡っていると\n露店を出していたマホに声をかけられる。", 20063115, "マホとの出会い", "フリーマーケット会場", 7, 0, 8, 40, 2, 2835);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("お嬢さまからの\n緊急依頼", 1, 91002, 10118, 5118063, "ジータが騎空団への依頼を確認していると、\n高笑いをしながらアキノが現れる。", 20063115, "アキノとの出会い", "ランドソル市街地", 7, 0, 8, 40, 2, 2837);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("黄金色の悩みごと", 1, 91002, 10118, 5118064, "ジータたちは、フリーマーケット会場で\n少し困った様子のジュンを見かける。", 20063115, "ジュンとの出会い", "フリーマーケット会場", 18, 0, 8, 40, 2, 4108402);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("白熱！　格闘大会！", 1, 91002, 10118, 5118065, "フリーマーケットの隅で開かれる格闘大会──\nそこにはカオリもいて……？", 20063115, "カオリとの出会い", "フリーマーケット会場", 18, 0, 8, 40, 2, 4107402);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("祭り太鼓はオーエドの華", 1, 91002, 10118, 5118066, "太鼓祭を控えるオーエド町──\nジータは、困った様子のニノンと出会う。", 20063115, "ニノンとの出会い", "オーエド町", 16, 1, 8, 40, 2, 9000227);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("人気者は遅れて\nやってくる", 1, 91002, 10118, 5118067, "ビカラはイベントに出演中のスズナを見かける。\nしかし、スズナはどこか困っているようで……？", 20063115, "スズナとの出会い", "フリーマーケット会場", 19, 0, 8, 40, 3, 2101181);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("巫女・ミーツ・魔法少女", 1, 91002, 10118, 5118068, "ビカラたちが街を散策していると、通りかかった\nナナカが興奮した様子で近づいてきて……？", 20063115, "ナナカとの出会い", "ランドソル市街地", 18, 0, 8, 40, 3, 4109402);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("ネズ耳は二度なくなる", 1, 91002, 10118, 5118069, "ネズ耳をなくしてしまい絶望するビカラ。同じ頃\nキャルとコッコロは落とし物を拾っており……", 20063115, "キャル＆コッコロとの出会い", "フリーマーケット会場", 18, 0, 8, 40, 3, 4305402);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("この出会いにカンパイ！", 1, 91002, 10118, 5118070, "街外れでひと休みをしていたビカラたちは、\nすっかりゴキゲンな様子のユカリと出会う。", 20063115, "ユカリとの出会い", "ランドソル市街地", 18, 0, 8, 40, 3, 4101402);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("陰陽アンサンブル", 1, 91002, 10118, 5118071, "ビカラは、人混みに怯えるアオイを心配し、\n陽気に声をかけるも……", 20063115, "アオイとの出会い", "ランドソル市街地", 18, 0, 8, 40, 3, 4106402);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("運試し十番勝負！", 1, 91002, 10118, 5118072, "ビカラがフリーマーケット会場を歩いていると\n占いをしていたシノブに声をかけられる。", 20063115, "シノブとの出会い", "フリーマーケット会場", 7, 1, 8, 40, 3, 2836);
INSERT INTO `v1_06146bfb06fa8e162b7f1beee1cf9eefd965674e00766e9d524e6d286445d110` VALUES ("彼女たちの新たな日常", 0, 0, 10118, 5118600, 0, 20063115, "オープニング", 0, 0, 0, 0, 0, 1, 0);
